for lang, kvs in AUTH_DATA.items():
    pattern = rf'(  {lang}:\s*\{{)'
    match = re.search(pattern, content)
    if match:
        insert_str = "\n" + "\n".join([f'    {k}: {repr(v)},' for k, v in kvs.items()])
        idx = match.end()
        content = content[:idx] + insert_str + content[idx:]
        print(f"Updated {lang} with {len(kvs)} auth keys")
    else:
        print(f"Warning: Could not find block for {lang}")

with open(file_path, "w", encoding="utf-8") as f:
    f.write(content)

print("Successfully injected all auth translations!")
